type Role = 'customer' | 'business' | 'rider';
type View = 'home' | 'discover' | 'orders' | 'wallet' | 'messages' | 'profile' | 'business' | 'rider';
type OrderStatus = 'Preparing' | 'Rider assigned' | 'On the way' | 'Delivered';

interface Profile { id: string; name: string; role: Role; location: string; balance: number; phone: string; email: string; }
interface Business { id: string; name: string; category: string; rating: number; distance: string; open: boolean; deliveryTime: string; cover: string; accent: string; blurb: string; }
interface Product { id: string; name: string; price: number; category: string; business: string; image: string; stock: number; description: string; }
interface Order { id: string; business: string; items: { name: string; quantity: number; price: number }[]; total: number; status: OrderStatus; eta: string; address: string; rider: string; created: string; }
interface Message { id: string; name: string; initials: string; preview: string; time: string; unread: number; type: 'business' | 'rider'; }
interface Notification { id: string; title: string; body: string; time: string; read: boolean; kind: 'order' | 'wallet' | 'tip'; }

